import { app } from 'electron';
import { createHash } from 'node:crypto';
import { spawn } from 'node:child_process';
import { mkdir, rename, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';

/**
 * Updates only from the public, CI-proven official GitHub Release channel.
 *
 * No remote commands, no arbitrary URLs, no self-update of source files.
 * A SHA-256 checksum generated by the Windows CI release job is mandatory.
 * Unreleased / failed / prerelease builds never enter the update channel.
 */
const REPOSITORY = 'rssen-debug/ai-teammates';
const RELEASE_API = `https://api.github.com/repos/${REPOSITORY}/releases/latest`;

interface ReleaseAsset {
  name: string;
  browser_download_url: string;
  digest?: string | null;
}
interface GitHubRelease {
  tag_name: string;
  draft: boolean;
  prerelease: boolean;
  assets: ReleaseAsset[];
}

const HEADERS = {
  'User-Agent': 'Studdy-Buddy-Windows-Updater',
  Accept: 'application/vnd.github+json',
};

function parseVersion(value: string): number[] | null {
  const normalized = value.replace(/^studdy-buddy-v/, '').replace(/^v/, '');
  if (!/^\d+\.\d+\.\d+$/.test(normalized)) return null;
  return normalized.split('.').map(Number);
}

function isNewer(remote: string, local: string): boolean {
  const r = parseVersion(remote);
  const l = parseVersion(local);
  if (!r || !l) return false;
  for (let index = 0; index < 3; index += 1) {
    if (r[index] !== l[index]) return r[index]! > l[index]!;
  }
  return false;
}

function trustedReleaseUrl(url: string): boolean {
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'https:' &&
      parsed.hostname === 'github.com' &&
      parsed.pathname.startsWith('/' + REPOSITORY + '/releases/download/');
  } catch {
    return false;
  }
}

async function getText(url: string): Promise<string> {
  if (!trustedReleaseUrl(url)) throw new Error('Untrusted update URL');
  const res = await fetch(url, { headers: HEADERS, signal: AbortSignal.timeout(30000) });
  if (!res.ok) throw new Error(`Update manifest HTTP ${res.status}`);
  return res.text();
}

let updateActive = false;

export async function checkAndInstallUpdate(): Promise<void> {
  if (updateActive || !app.isPackaged || process.platform !== 'win32') return;
  updateActive = true;
  try {
    const response = await fetch(RELEASE_API, {
      headers: HEADERS,
      signal: AbortSignal.timeout(15000),
      cache: 'no-store',
    });
    if (!response.ok) throw new Error(`Release lookup HTTP ${response.status}`);
    const release = (await response.json()) as GitHubRelease;
    if (release.draft || release.prerelease || !isNewer(release.tag_name, app.getVersion())) return;

    const installer = release.assets.find((asset) =>
      /^Studdy Buddy-\d+\.\d+\.\d+-x64\.exe$/.test(asset.name),
    );
    if (!installer || !trustedReleaseUrl(installer.browser_download_url)) {
      throw new Error('Release has no official x64 installer');
    }
    const checksum = release.assets.find((asset) => asset.name === installer.name + '.sha256');
    if (!checksum) throw new Error('Release has no checksum for installer');
    const manifest = await getText(checksum.browser_download_url);
    const expected = manifest.trim().split(/\s+/)[0]?.toLowerCase();
    if (!expected || !/^[a-f0-9]{64}$/.test(expected)) throw new Error('Invalid update checksum');
    if (installer.digest && installer.digest !== 'sha256:' + expected) {
      throw new Error('Release checksum and GitHub digest disagree');
    }

    const downloaded = await fetch(installer.browser_download_url, {
      headers: HEADERS,
      signal: AbortSignal.timeout(180000),
    });
    if (!downloaded.ok) throw new Error(`Installer HTTP ${downloaded.status}`);
    const bytes = Buffer.from(await downloaded.arrayBuffer());
    const actual = createHash('sha256').update(bytes).digest('hex');
    if (actual !== expected) throw new Error('Installer checksum mismatch — refused to install');

    const updates = join(app.getPath('userData'), 'updates');
    await mkdir(updates, { recursive: true });
    const target = join(updates, installer.name);
    const partial = target + '.partial';
    await writeFile(partial, bytes);
    await rename(partial, target);
    console.info(`[auto-update] verified ${release.tag_name}. Starting silent NSIS installer.`);

    // No elevated privileges; per-user NSIS installer, same installation path.
    // Child can continue after Buddy exits, which releases its executable.
    const install = spawn(target, ['/S', `/D=${dirname(process.execPath)}`], {
      detached: true,
      stdio: 'ignore',
      windowsHide: true,
    });
    install.on('error', (error) => console.error('[auto-update] installer:', error.message));
    install.unref();
    setTimeout(() => app.quit(), 1200);
  } catch (error) {
    console.warn('[auto-update] no update installed:', error instanceof Error ? error.message : String(error));
  } finally {
    updateActive = false;
  }
}

/** Start after UI startup; recheck periodically without interrupting normal study. */
export function startAutomaticUpdates(): void {
  if (!app.isPackaged || process.platform !== 'win32') return;
  setTimeout(() => void checkAndInstallUpdate(), 15_000);
  // Approximately two minutes after a verified release is published, without
  // exhausting GitHub's unauthenticated API rate limits.
  const interval = setInterval(() => void checkAndInstallUpdate(), 2 * 60_000);
  interval.unref();
}
